const http = require("https");

const options = {
  "method": "GET",
  "hostname": "soil.api.dtn.com",
  "port": null,
  "path": "/v1/?lat=SOME_NUMBER_VALUE&lon=SOME_NUMBER_VALUE&startTime=SOME_STRING_VALUE&endTime=SOME_STRING_VALUE&parameters=SOME_ARRAY_VALUE&units=SOME_STRING_VALUE",
  "headers": {
    "Accept-Encoding": "SOME_STRING_VALUE",
    "Accept": "SOME_STRING_VALUE",
    "Authorization": "Bearer REPLACE_BEARER_TOKEN"
  }
};

const req = http.request(options, function (res) {
  const chunks = [];

  res.on("data", function (chunk) {
    chunks.push(chunk);
  });

  res.on("end", function () {
    const body = Buffer.concat(chunks);
    console.log(body.toString());
  });
});

req.end();

